import json,subprocess,base64,hashlib,concurrent.futures
from pathlib import Path
b=Path('docs/developer/final-acceptance/wave-04/coordinator/upstream-provenance');m=json.loads(Path('docs/extraction-manifest.json').read_text());c=json.loads(subprocess.check_output(['gh','api',f"repos/{m['sourceRepository']}/git/commits/{m['sourceCommit']}"]));t=json.loads(subprocess.check_output(['gh','api',f"repos/{m['sourceRepository']}/git/trees/{c['tree']['sha']}?recursive=1"]));assert c['sha']==m['sourceCommit'];assert t['sha']==c['tree']['sha'];assert not t['truncated'];tree={e['path']:e for e in t['tree']};rows=[]
for f in m['files']:
 e=tree[m['sourceRoot']+'/'+f['source']];assert e['type']=='blob';path='src/'+f['source'];v=subprocess.run(['git','rev-parse','21adebd:'+path],capture_output=True,text=True);local=v.stdout.strip() if v.returncode==0 else None
 rows.append({'source':f['source'],'upstreamBlob':e['sha'],'bytes':e['size'],'initialLocalPath':path,'initialLocalBlob':local,'initialLocalBytesEqual':local==e['sha']})
(b/'verified-source-inventory.json').write_text(json.dumps({'repository':m['sourceRepository'],'commit':c['sha'],'resolvedTree':t['sha'],'sourceRoot':m['sourceRoot'],'files':rows,'upstreamWrites':0,'methods':['GET git/commits/<sha>','GET git/trees/<resolved-tree>?recursive=1','GET git/blobs/<story-blob>'],'limits':'Read-only verification at original immutable commit; no claim about unrelated historical or current application changes.'},indent=2)+'\n')
stories=[r for r in rows if '.stories.' in r['source']];out=b/'local-stories';out.mkdir(exist_ok=True)
def fetch(r):
 raw=subprocess.check_output(['gh','api',f"repos/{m['sourceRepository']}/git/blobs/{r['upstreamBlob']}"]);j=json.loads(raw);assert j['sha']==r['upstreamBlob'];data=base64.b64decode(j['content']);assert len(data)==r['bytes'];assert hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()==r['upstreamBlob'];p=out/(r['source'].replace('/','__')+'.txt');p.write_bytes(data);return {**r,'sha256':hashlib.sha256(data).hexdigest(),'localArtifact':str(p),'upstreamUrl':f"https://github.com/{m['sourceRepository']}/blob/{c['sha']}/{m['sourceRoot']}/{r['source']}"}
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:result=list(pool.map(fetch,stories))
(b/'verified-story-sources.json').write_text(json.dumps({'count':len(result),'stories':result,'rawRetention':'local-only source data; not application code, not executed, not Git added'},indent=2)+'\n');print('Verified',len(rows),'upstream source paths;',sum(r['initialLocalBytesEqual'] for r in rows),'exact initial local blobs;',len(result),'story blobs downloaded and hash verified read-only')
